WITH with_windows AS (SELECT *, LAG(unit_price) OVER w_recent AS prev_unit_price, LEAD(unit_price) OVER w_recent AS next_unit_price, LEAD(quantity) OVER w_recent AS next_quantity, LAG(quantity) OVER w_recent AS prev_quantity, ROW_NUMBER() OVER w_recent AS event_seq, LEAD(unit_price, 1) OVER w_ordered AS next_unit_price_2 FROM order_items WINDOW w_recent AS (PARTITION BY product_id ORDER BY quantity, id), w_ordered AS (ORDER BY quantity, id)) SELECT s.id, s.order_id, s.product_id, s.quantity, s.prev_unit_price, s.next_unit_price, s.next_quantity, s.event_seq, s.next_unit_price_2, (SELECT MAX(p2.amount) FROM payments p2 WHERE p2.order_id = s.order_id) AS max_payment_amount FROM with_windows s ORDER BY id
